from collections.abc import Generator, Iterable, Iterator
from dataclasses import dataclass
from xml.etree.ElementTree import Element

from ..utils import ensure_list, is_the_same, nest
from pdf_craft.transformer.xml_translator.xml import ID_KEY, append_text_in_element, iter_with_stack, plain_text
from .common import FoundInvalidIDError, validate_id_in_element
from .text_segment import TextSegment
from .utils import IDGenerator, element_fingerprint, id_in_element


@dataclass
class InlineLostIDError:
    element: Element
    stack: list[Element]


@dataclass
class InlineUnexpectedIDError:
    id: int
    element: Element


@dataclass
class InlineExpectedIDsError:
    id2element: dict[int, Element]


@dataclass
class InlineWrongTagCountError:
    expected_count: int
    found_elements: list[Element]
    stack: list[Element]


InlineError = InlineLostIDError | InlineUnexpectedIDError | InlineExpectedIDsError | InlineWrongTagCountError


def search_inline_segments(text_segments: Iterable[TextSegment]) -> Generator["InlineSegment", None, None]:
    stack_data: tuple[list[list[TextSegment | InlineSegment]], Element, int] | None = None
    inline_segment: InlineSegment | None = None

    for text_segment in text_segments:
        if stack_data is not None:
            stack, stack_block, stack_base_depth = stack_data
            if stack_block is not text_segment.block_parent:
                inline_segment = _pop_stack_data(stack_data)
                stack_data = None
                if inline_segment:
                    inline_segment.id = 0
                    yield inline_segment

        if stack_data is None:
            stack_data = (
                [],
                text_segment.block_parent,
                text_segment.block_depth,
            )

        stack, stack_block, stack_base_depth = stack_data

        while len(stack) < text_segment.depth + 1:
            stack.append([])

        while len(stack) > text_segment.depth + 1:
            _pop_stack(
                stack=stack,
                stack_base_depth=stack_base_depth,
            )

        # text_segment.depth 可视为它在 stack 中的 index，必须令 len(stack) == text_segment.depth + 1
        stack[-1].append(text_segment)

    if stack_data is not None:
        inline_segment = _pop_stack_data(stack_data)
        if inline_segment:
            inline_segment.id = 0
            yield inline_segment


def _pop_stack_data(stack_data: tuple[list[list["TextSegment | InlineSegment"]], Element, int]):
    stack, _, stack_base_depth = stack_data
    inline_segment: InlineSegment | None = None
    while stack:
        inline_segment = _pop_stack(
            stack=stack,
            stack_base_depth=stack_base_depth,
        )
    return inline_segment


def _pop_stack(
    stack: list[list["TextSegment | InlineSegment"]],
    stack_base_depth: int,
) -> "InlineSegment | None":
    inline_segment: InlineSegment | None = None
    depth = len(stack) + stack_base_depth - 1
    popped = stack.pop()
    if popped:
        inline_segment = InlineSegment(depth, popped)
    if stack and inline_segment is not None:
        stack[-1].append(inline_segment)
    return inline_segment


class InlineSegment:
    def __init__(self, depth: int, children: list["TextSegment | InlineSegment"]) -> None:
        assert depth > 0
        self.id: int | None = None
        self._children: list[TextSegment | InlineSegment] = children
        self._parent_stack: list[Element] = children[0].parent_stack[:depth]

        # 每一组 tag 都对应一个 ids 列表。
        # 若为空，说明该 tag 属性结构全同，没必要分配 id 以区分。
        # 若非空，则表示 tag 下每一个 element 都有 id 属性。
        # 注意，相同 tag 下的 element 要么全部有 id，要么全部都没有 id
        self._child_tag2ids: dict[str, list[int]] = {}
        self._child_tag2count: dict[str, int] = {}

        next_temp_id: int = 1
        terms = nest((child.parent.tag, child) for child in children if isinstance(child, InlineSegment))

        for tag, child_terms in terms.items():
            self._child_tag2count[tag] = len(child_terms)
            if not is_the_same(  # 仅当 tag 彼此无法区分时才分配 id，以尽可能减少 id 的数量
                elements=(element_fingerprint(t.parent) for t in child_terms),
            ):
                for child in child_terms:
                    child.id = next_temp_id
                    next_temp_id += 1

    @property
    def head(self) -> TextSegment:
        first_child = self._children[0]
        if isinstance(first_child, TextSegment):
            return first_child
        else:
            return first_child.head

    @property
    def tail(self) -> TextSegment:
        last_child = self._children[-1]
        if isinstance(last_child, TextSegment):
            return last_child
        else:
            return last_child.tail

    @property
    def children(self) -> list["TextSegment | InlineSegment"]:
        return self._children

    @property
    def parent(self) -> Element:
        return self._parent_stack[-1]

    @property
    def parent_stack(self) -> list[Element]:
        return self._parent_stack

    def __iter__(self) -> Iterator[TextSegment]:
        for child in self._children:
            if isinstance(child, TextSegment):
                yield child
            elif isinstance(child, InlineSegment):
                yield from child

    def clone(self) -> "InlineSegment":
        cloned_segment = InlineSegment(
            depth=len(self._parent_stack),
            children=[child.clone() for child in self._children],
        )
        cloned_segment.id = self.id
        return cloned_segment

    def recreate_ids(self, id_generator: IDGenerator) -> None:
        self._child_tag2count.clear()
        self._child_tag2ids.clear()

        for child in self._children:
            if isinstance(child, InlineSegment):
                child_tag = child.parent.tag
                ids = ensure_list(self._child_tag2ids, child_tag)
                if child.id is not None:
                    child.id = id_generator.next_id()
                    ids.append(child.id)
                child.recreate_ids(id_generator)
                self._child_tag2count[child_tag] = self._child_tag2count.get(child_tag, 0) + 1

    def create_element(self) -> Element:
        element = Element(self.parent.tag)
        previous_element: Element | None = None
        for child in self._children:
            if isinstance(child, InlineSegment):
                previous_element = child.create_element()
                element.append(previous_element)

            elif isinstance(child, TextSegment):
                if previous_element is None:
                    element.text = append_text_in_element(
                        origin_text=element.text,
                        append_text=child.text,
                    )
                else:
                    previous_element.tail = append_text_in_element(
                        origin_text=previous_element.tail,
                        append_text=child.text,
                    )
        if self.id is not None:
            element.set(ID_KEY, str(self.id))
        return element

    def validate(self, validated_element: Element) -> Generator[InlineError | FoundInvalidIDError, None, None]:
        remain_expected_elements: dict[int, Element] = {}
        for child in self._child_inline_segments():
            if child.id is not None:
                remain_expected_elements[child.id] = child.parent

        for _, child_element in iter_with_stack(validated_element):
            if child_element is validated_element:
                continue  # skip the root self

            element_id = id_in_element(child_element)
            if element_id is None:
                validated_id = validate_id_in_element(
                    element=child_element,
                    enable_no_id=True,
                )
                if isinstance(validated_id, FoundInvalidIDError):
                    yield validated_id
                continue

            remain_expected_element = remain_expected_elements.pop(element_id, None)
            if remain_expected_element is None:
                yield InlineUnexpectedIDError(
                    id=element_id,
                    element=child_element,
                )

        if remain_expected_elements:
            yield InlineExpectedIDsError(
                id2element=remain_expected_elements,
            )

        yield from self._validate_children_structure(validated_element)

    def _child_inline_segments(self) -> Generator["InlineSegment", None, None]:
        for child in self._children:
            if isinstance(child, InlineSegment):
                yield child
                yield from child._child_inline_segments()  # pylint: disable=protected-access

    def _validate_children_structure(self, validated_element: Element):
        tag2found_elements: dict[str, list[Element]] = {}

        for child_element in validated_element:
            ids = self._child_tag2ids.get(child_element.tag, None)
            if not ids:
                found_elements = ensure_list(tag2found_elements, child_element.tag)
                found_elements.append(child_element)
            else:
                id_str = child_element.get(ID_KEY, None)
                if id_str is None:
                    yield InlineLostIDError(
                        element=child_element,
                        stack=[self.parent],
                    )

        for tag, found_elements in tag2found_elements.items():
            expected_count = self._child_tag2count.get(tag, 0)
            if len(found_elements) != expected_count:
                yield InlineWrongTagCountError(
                    expected_count=expected_count,
                    found_elements=found_elements,
                    stack=[self.parent],
                )

        for child, child_element in self._match_children(validated_element):
            # pylint: disable=protected-access
            for error in child._validate_children_structure(child_element):
                error.stack.insert(0, self.parent)
                yield error

    # 即便 self.validate(...) 的错误没有排除干净，也要尽可能匹配一个质量较高（尽力而为）的版本
    def assign_attributes(self, template_element: Element) -> Element:
        assigned_element = Element(self.parent.tag, self.parent.attrib)
        if template_element.text and template_element.text.strip():
            assigned_element.text = append_text_in_element(
                origin_text=assigned_element.text,
                append_text=template_element.text,
            )

        matched_child_element_ids: set[int] = set()
        for child, child_element in self._match_children(template_element):
            child_assigned_element = child.assign_attributes(child_element)
            assigned_element.append(child_assigned_element)
            matched_child_element_ids.add(id(child_element))

        assigned_child_element_stack = list(assigned_element)
        assigned_child_element_stack.reverse()

        previous_assigned_child_element: Element | None = None
        for child_element in template_element:
            # 只关心 child_element 是否是分割点，不关心它真实对应。极端情况下可能乱序，只好大致对上就行
            child_text: str = ""
            if id(child_element) not in matched_child_element_ids:
                child_text = plain_text(child_element)
            elif assigned_child_element_stack:
                previous_assigned_child_element = assigned_child_element_stack.pop()
            if child_element.tail is not None:
                child_text += child_element.tail
            if not child_text.strip():
                continue
            if previous_assigned_child_element is None:
                assigned_element.text = append_text_in_element(
                    origin_text=assigned_element.text,
                    append_text=child_text,
                )
            else:
                previous_assigned_child_element.tail = append_text_in_element(
                    origin_text=previous_assigned_child_element.tail,
                    append_text=child_text,
                )
        return assigned_element

    def _match_children(self, element: Element) -> Generator[tuple["InlineSegment", Element], None, None]:
        tag2elements = nest((c.tag, c) for c in element)
        tag2children = nest(
            (c.parent.tag, (i, c)) for i, c in enumerate(c for c in self._children if isinstance(c, InlineSegment))
        )
        used_ids: set[int] = set()
        children_and_elements: list[tuple[int, InlineSegment, Element]] = []

        for tag, orders_and_children in tag2children.items():
            # 优先考虑 id 匹配，剩下的以自然顺序尽可能匹配
            ids = self._child_tag2ids.get(tag, [])
            matched_children_elements: list[Element | None] = [None] * len(orders_and_children)
            not_matched_elements: list[Element] = []

            for child_element in tag2elements.get(tag, []):
                id_order: int | None = None
                child_id = id_in_element(child_element)
                if child_id is not None and child_id not in used_ids:
                    used_ids.add(child_id)  # 一个 id 只能用一次，防止重复
                    try:
                        id_order = ids.index(child_id)
                    except ValueError:
                        pass
                if id_order is None:
                    not_matched_elements.append(child_element)
                else:
                    matched_children_elements[id_order] = child_element

            not_matched_elements.reverse()
            for i in range(len(matched_children_elements)):
                if not not_matched_elements:
                    break
                matched_element = matched_children_elements[i]
                if matched_element is None:
                    matched_children_elements[i] = not_matched_elements.pop()

            for (order, child), child_element in zip(orders_and_children, matched_children_elements):
                if child_element is not None:
                    children_and_elements.append((order, child, child_element))

        for _, child, child_element in sorted(children_and_elements, key=lambda x: x[0]):
            yield child, child_element

from collections.abc import Generator
from dataclasses import dataclass
from typing import cast
from xml.etree.ElementTree import Element

from .common import FoundInvalidIDError, validate_id_in_element
from .inline_segment import InlineError, InlineSegment
from .text_segment import TextSegment
from .utils import IDGenerator, id_in_element


@dataclass
class BlockSubmitter:
    id: int
    origin_text_segments: list[TextSegment]
    submitted_element: Element


@dataclass
class BlockWrongTagError:
    block: tuple[int, Element] | None  # (block_id, block_element) | None 表示根元素
    expected_tag: str
    instead_tag: str


@dataclass
class BlockUnexpectedIDError:
    id: int
    element: Element


@dataclass
class BlockExpectedIDsError:
    id2element: dict[int, Element]


@dataclass
class BlockContentError:
    id: int
    element: Element
    errors: list[InlineError | FoundInvalidIDError]


BlockError = BlockWrongTagError | BlockUnexpectedIDError | BlockExpectedIDsError | BlockContentError


class BlockSegment:
    def __init__(self, root_tag: str, inline_segments: list[InlineSegment]) -> None:
        id_generator = IDGenerator()
        for inline_segment in inline_segments:
            inline_segment.id = id_generator.next_id()
            inline_segment.recreate_ids(id_generator)

        self._root_tag: str = root_tag
        self._inline_segments: list[InlineSegment] = inline_segments
        self._id2inline_segment: dict[int, InlineSegment] = dict((cast(int, s.id), s) for s in self._inline_segments)

    def __iter__(self) -> Generator[InlineSegment, None, None]:
        yield from self._inline_segments

    def create_element(self) -> Element:
        root_element = Element(self._root_tag)
        for inline_segment in self._inline_segments:
            root_element.append(inline_segment.create_element())
        return root_element

    def validate(self, validated_element: Element) -> Generator[BlockError | FoundInvalidIDError, None, None]:
        if validated_element.tag != self._root_tag:
            yield BlockWrongTagError(
                block=None,
                expected_tag=self._root_tag,
                instead_tag=validated_element.tag,
            )

        remain_expected_elements: dict[int, Element] = dict(
            (id, inline_segment.parent) for id, inline_segment in self._id2inline_segment.items()
        )
        for child_validated_element in validated_element:
            element_id = validate_id_in_element(child_validated_element)
            if isinstance(element_id, FoundInvalidIDError):
                yield element_id
            else:
                inline_segment = self._id2inline_segment.get(element_id, None)
                if inline_segment is None:
                    yield BlockUnexpectedIDError(
                        id=element_id,
                        element=child_validated_element,
                    )
                else:
                    if inline_segment.parent.tag != child_validated_element.tag:
                        yield BlockWrongTagError(
                            block=(cast(int, inline_segment.id), inline_segment.parent),
                            expected_tag=inline_segment.parent.tag,
                            instead_tag=child_validated_element.tag,
                        )

                    remain_expected_elements.pop(element_id, None)
                    inline_errors = list(inline_segment.validate(child_validated_element))

                    if inline_errors:
                        yield BlockContentError(
                            id=element_id,
                            element=child_validated_element,
                            errors=inline_errors,
                        )

        if remain_expected_elements:
            yield BlockExpectedIDsError(id2element=remain_expected_elements)

    def submit(self, target: Element) -> Generator[BlockSubmitter, None, None]:
        for child_element in target:
            element_id = id_in_element(child_element)
            if element_id is None:
                continue
            inline_segment = self._id2inline_segment.get(element_id, None)
            if inline_segment is None:
                continue
            inline_segment_id = inline_segment.id
            assert inline_segment_id is not None
            yield BlockSubmitter(
                id=inline_segment_id,
                origin_text_segments=list(inline_segment),
                submitted_element=inline_segment.assign_attributes(child_element),
            )

from collections.abc import Callable, Generator, Iterable

from .chunk import split_into_chunks
from .segment import ST, T


def split(
    segments: Iterable[ST],
    transform: Callable[[list[ST]], list[T]],
    max_group_tokens: int,
) -> Generator[T, None, None]:
    for group in split_into_chunks(segments, max_group_tokens):
        head = list(
            _truncate_extra_content(
                segments=group.head,
                remain_left=False,
                remain_tokens=group.head_remain_tokens,
            )
        )
        tail = list(
            _truncate_extra_content(
                segments=group.tail,
                remain_left=True,
                remain_tokens=group.tail_remain_tokens,
            )
        )
        transformed = transform(head + group.body + tail)

        if len(tail) > 0:  # 避免 target[N:-0] 切片错误
            yield from transformed[len(head) : -len(tail)]
        else:
            yield from transformed[len(head) :]


def _truncate_extra_content(segments: list[ST], remain_left: bool, remain_tokens: int):
    tokens_list: list[int] = [segment.tokens for segment in segments]
    segments = list(segments)
    for tokens in tokens_list if remain_left else reversed(tokens_list):
        if remain_tokens <= 0:
            break
        next_segment = segments.pop(0) if remain_left else segments.pop()
        if remain_tokens < tokens:
            if remain_left:
                next_segment = next_segment.truncate_after_head(remain_tokens)
            else:
                next_segment = next_segment.truncate_before_tail(remain_tokens)
            remain_tokens = 0
        else:
            remain_tokens -= tokens
        yield next_segment

from collections.abc import Generator, Iterable
from dataclasses import dataclass
from typing import Generic

from resource_segmentation import Resource, Segment, split

from .segment import ST

_INCISION = 0


@dataclass
class Chunk(Generic[ST]):
    head_remain_tokens: int
    tail_remain_tokens: int
    head: list[ST]
    body: list[ST]
    tail: list[ST]


def split_into_chunks(segments: Iterable[ST], max_group_tokens: int) -> Generator[Chunk[ST], None, None]:
    for group in split(
        max_segment_count=max_group_tokens,
        gap_rate=0.07,
        tail_rate=0.5,
        border_incision=_INCISION,
        resources=(
            Resource(
                count=segment.tokens,
                start_incision=_INCISION,
                end_incision=_INCISION,
                payload=segment,
            )
            for segment in segments
        ),
    ):
        yield Chunk(
            head_remain_tokens=group.head_remain_count,
            tail_remain_tokens=group.tail_remain_count,
            head=list(_expand_payloads(group.head)),
            body=list(_expand_payloads(group.body)),
            tail=list(_expand_payloads(group.tail)),
        )


def _expand_payloads(target: list[Resource[ST] | Segment[ST]]) -> Generator[ST, None, None]:
    for item in target:
        if isinstance(item, Resource):
            yield item.payload
        elif isinstance(item, Segment):
            for resource in item.resources:
                yield resource.payload

from collections.abc import Generator, Iterable
from dataclasses import dataclass
from enum import Enum, auto
from typing import Self
from xml.etree.ElementTree import Element

from pdf_craft.transformer.xml_translator.xml import (
    expand_left_element_texts,
    expand_right_element_texts,
    is_inline_element,
    normalize_text_in_element,
)


class TextPosition(Enum):
    TEXT = auto()
    TAIL = auto()


@dataclass
class TextSegment:
    text: str
    parent_stack: list[Element]
    left_common_depth: int
    right_common_depth: int
    block_depth: int
    position: TextPosition

    @property
    def root(self) -> Element:
        return self.parent_stack[0]

    @property
    def depth(self) -> int:
        return len(self.parent_stack) - self.block_depth

    @property
    def block_parent(self) -> Element:
        return self.parent_stack[self.block_depth - 1]

    def strip_block_parents(self) -> Self:
        self.parent_stack = self.parent_stack[self.block_depth - 1 :]
        self.block_depth = 1
        return self

    def clone(self) -> "TextSegment":
        return TextSegment(
            text=self.text,
            parent_stack=list(self.parent_stack),
            left_common_depth=self.left_common_depth,
            right_common_depth=self.right_common_depth,
            block_depth=self.block_depth,
            position=self.position,
        )


def _expand_xml_texts(segment: TextSegment):
    for i in range(segment.left_common_depth, len(segment.parent_stack)):
        yield from expand_left_element_texts(segment.parent_stack[i])
    yield segment.text
    for i in range(len(segment.parent_stack) - 1, segment.right_common_depth - 1, -1):
        yield from expand_right_element_texts(segment.parent_stack[i])


def incision_between(segment1: TextSegment, segment2: TextSegment) -> tuple[int, int]:
    return (
        _incision_of(segment1, segment1.right_common_depth),
        _incision_of(segment2, segment2.left_common_depth),
    )


def _incision_of(segment: TextSegment, common_depth: int) -> int:
    block_diff: int = 0
    inline_diff: int = 0
    if common_depth >= segment.block_depth:
        inline_diff = len(segment.parent_stack) - common_depth
    else:
        block_diff = segment.block_depth - common_depth
        inline_diff = len(segment.parent_stack) - segment.block_depth
    return block_diff * 3 + inline_diff  # 数字越大越容易被拆分


def search_text_segments(root: Element) -> Generator[TextSegment, None, None]:
    generator = _search_text_segments([], root)
    text_segment = next(generator, None)
    if text_segment is None:
        return

    while True:
        next_text_segment = next(generator, None)
        if next_text_segment is None:
            break
        common_depth = _common_depth(
            stack1=text_segment.parent_stack,
            stack2=next_text_segment.parent_stack,
        )
        text_segment.right_common_depth = common_depth
        yield text_segment
        text_segment = next_text_segment
        text_segment.left_common_depth = common_depth

    yield text_segment


def _search_text_segments(stack: list[Element], element: Element) -> Generator[TextSegment, None, None]:
    text = normalize_text_in_element(element.text)
    next_stack = stack + [element]
    next_block_depth = find_block_depth(next_stack)

    if text is not None:
        yield TextSegment(
            text=text,
            parent_stack=next_stack,
            left_common_depth=0,
            right_common_depth=0,
            block_depth=next_block_depth,
            position=TextPosition.TEXT,
        )
    for child_element in element:
        yield from _search_text_segments(next_stack, child_element)
        child_tail = normalize_text_in_element(child_element.tail)
        if child_tail is not None:
            yield TextSegment(
                text=child_tail,
                parent_stack=next_stack,
                left_common_depth=0,
                right_common_depth=0,
                block_depth=next_block_depth,
                position=TextPosition.TAIL,
            )


def find_block_depth(parent_stack: list[Element]) -> int:
    index: int = 0
    for i in range(len(parent_stack)):
        if not is_inline_element(parent_stack[i]):
            index = i
    return index + 1  # depth is a count not index


def combine_text_segments(segments: Iterable[TextSegment]) -> Generator[tuple[Element, dict[int, Element]], None, None]:
    stack: list[tuple[Element, Element]] = []  # (raw, generated)
    raw2generated: dict[int, Element] = {}
    last_popped: Element | None = None

    for segment in segments:
        common_depth = _common_depth(
            stack1=(raw for raw, _ in stack),
            stack2=segment.parent_stack,
        )
        if stack and common_depth == 0:
            yield stack[0][1], raw2generated
            stack = []
            raw2generated = {}
            last_popped = None

        while len(stack) > common_depth:
            last_popped = stack.pop()[1]
        while len(stack) < len(segment.parent_stack):
            last_popped = None
            index = len(stack)
            raw = segment.parent_stack[index]
            generated = Element(raw.tag, raw.attrib)
            if stack:
                _, generated_parent = stack[-1]
                generated_parent.append(generated)
            stack.append((raw, generated))
            raw2generated[id(raw)] = generated

        if last_popped is None:
            if stack:
                stack[-1][1].text = _append_element_text(
                    text=stack[-1][1].text,
                    appended=segment.text,
                )
        else:
            last_popped.tail = _append_element_text(
                text=last_popped.tail,
                appended=segment.text,
            )
    if stack:
        yield stack[0][1], raw2generated


def _common_depth(stack1: Iterable[Element], stack2: Iterable[Element]) -> int:
    common_depth: int = 0
    for parent1, parent2 in zip(stack1, stack2):
        if id(parent1) != id(parent2):
            break
        common_depth += 1
    return common_depth


def _append_element_text(text: str | None, appended: str) -> str:
    if text is None:
        return appended
    else:
        return text + appended

